package ec.edu.unl.sec.selfassessment.application;
import ec.edu.unl.sec.identityaccess.application.*;import ec.edu.unl.sec.identityaccess.domain.*;import ec.edu.unl.sec.selfassessment.domain.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ProcessTransitionService{private final SelfAssessmentRepository repository;private final CurrentActorPort actors;private final AuthorizationPort auth;private final SelfAssessmentAuditService audit;public ProcessTransitionService(SelfAssessmentRepository repository,CurrentActorPort actors,AuthorizationPort auth,SelfAssessmentAuditService audit){this.repository=repository;this.actors=actors;this.auth=auth;this.audit=audit;}@Transactional public SelfAssessmentProcess transition(UUID id,long expected,ProcessState target,String reason,UUID correlation){var p=repository.find(id).orElseThrow(()->SelfAssessmentService.problem(ProcessProblemException.Kind.NOT_FOUND,"PROCESS_NOT_FOUND","El proceso no existe o no está visible."));var actor=actors.currentActor().orElseThrow(()->SelfAssessmentService.problem(ProcessProblemException.Kind.UNAUTHORIZED,"AUTHENTICATION_REQUIRED","Se requiere autenticación."));if(actor.technical()||!auth.isAllowed(actor.identityId(),OperationCode.PROCESS_COORDINATE,new AuthorizationScope(p.careerId(),p.id(),null)))throw SelfAssessmentService.problem(ProcessProblemException.Kind.FORBIDDEN,"PROCESS_SCOPE_DENIED","La operación no está permitida.");SelfAssessmentService.check(p,expected);if(target==ProcessState.REOPENED&&(reason==null||reason.isBlank()))throw SelfAssessmentService.problem(ProcessProblemException.Kind.INVALID,"REOPEN_REASON_REQUIRED","La reapertura requiere motivo.");try{var changed=p.transition(target);repository.save(changed,expected);repository.recordTransition(id,p.state(),target,actor.identityId(),reason,correlation,changed.revision());audit.record(actor.identityId(),correlation,target==ProcessState.REOPENED?"PROCESS_REOPENED":"PROCESS_TRANSITIONED",id,"SUCCESS",null);return changed;}catch(IllegalStateException e){audit.record(actor.identityId(),correlation,"PROCESS_TRANSITION_REJECTED",id,"REJECTED","INVALID_TRANSITION");throw SelfAssessmentService.problem(ProcessProblemException.Kind.CONFLICT,"INVALID_PROCESS_TRANSITION","La transición solicitada no está permitida.");}}}
